lynx.script:
const engine = lynx.getEngine();
const tapOptions = {};

let count = 0;
let countText;
let countRawText;
let button;

function createText(parentComponentId, className, value) {
  const text = __CreateText(parentComponentId);
  const rawText = __CreateRawText(value);
  __SetClasses(text, className);
  __AppendElement(text, rawText);
  return { text, rawText };
}

function increment() {
  count += 1;
  const nextRawText = __CreateRawText(String(count));
  __ReplaceElements(
    countText,
    [nextRawText],
    [countRawText],
  );
  countRawText = nextRawText;
  __FlushElementTree();
}

Object.assign(globalThis, {
  processData(data) {
    return data;
  },
});

function renderPage() {
  const page = __CreatePage("0", 0);
  const pageId = __GetElementUniqueID(page);
  __SetClasses(page, "page");

  const counter = __CreateView(pageId);
  __SetClasses(counter, "counter");

  const countNode = createText(pageId, "count", String(count));
  countText = countNode.text;
  countRawText = countNode.rawText;
  __AppendElement(counter, countText);

  button = __CreateView(pageId);
  __SetClasses(button, "button");
  __SetAttribute(button, "aria-label", "Increment counter");
  __AppendElement(
    button,
    createText(pageId, "button-text", "Add one").text,
  );
  __AddEventListener(button, "tap", increment, tapOptions);
  __AppendElement(counter, button);

  __AppendElement(page, counter);
}

engine.addEventListener("__RenderPage", renderPage);
